def roman_to_int(s):
    total = 0
    for i, ch in enumerate(s):
        val = VALUES[ch]
        # If a smaller value precedes a larger one, subtract it (subtractive notation)
        if i + 1 < len(s) and val < VALUES[s[i + 1]]:
            total -= val
        else:
            total += val
    return total

