def resolve_order(deps):
    # Collect all items (including those only mentioned as prerequisites)
    items = set(deps)
    for prereqs in deps.values():
        items.update(prereqs)

    # Build in-degree count and adjacency list (prereq -> dependents)
    in_degree = {item: 0 for item in items}
    dependents = {item: [] for item in items}

    for item, prereqs in deps.items():
        for prereq in prereqs:
            in_degree[item] += 1
            dependents[prereq].append(item)

    # Kahn's algorithm with a min-heap for lexicographic tie-breaking
    import heapq
    ready = [item for item in items if in_degree[item] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        item = heapq.heappop(ready)
        order.append(item)
        for dependent in dependents[item]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(ready, dependent)

    return order
